INSERT INTO expressions (english, translation, example, meaning) VALUES ('Find out', 'выяснить, узнать', 'Find out when the train leaves.', 'Find out — выяснить, узнать информацию; find out the truth.') ON CONFLICT DO NOTHING;
INSERT INTO expressions (english, translation, example, meaning) VALUES ('Set up', 'устанавливать, организовывать', 'They set up a new company.', 'Set up — устанавливать, организовывать; set up a meeting.') ON CONFLICT DO NOTHING;
INSERT INTO expressions (english, translation, example, meaning) VALUES ('Give up', 'сдаваться, бросать', 'Never give up!', 'Give up — сдаваться; бросать (привычку): give up smoking.') ON CONFLICT DO NOTHING;
