INSERT INTO expressions (english, translation, example, meaning) VALUES ('Give away', 'отдавать даром; выдавать', 'She gave away her old toys.', 'Give away — отдавать бесплатно; выдавать (секрет).') ON CONFLICT DO NOTHING;
